<?php
// Doctyn Academy FCCM LMS — ONE-FILE INSTALLER.
// Upload just this file to the folder where the LMS should live (e.g. public_html/lms), open it in your browser,
// choose an admin password, and it creates every folder and file for you. It deletes itself when finished.
@ini_set('display_errors', '0');
header('Content-Type: text/html; charset=utf-8');
header('Cache-Control: no-store');

$FILES = array(
    'index.html' => '',
    'css/style.css' => '',
    'js/app.js' => '',
    'js/ping.js' => '',
    'assets/logo.png' => '',
    'app.php' => '',
    'check.php' => '',
    '.htaccess' => '',
    '.user.ini' => 'OyBVc2VkIGJ5IFBIUC1GUE0gLyBDR0kgaG9zdHM6IG5ldmVyIHByaW50IFBIUCB3YXJuaW5ncyBpbnRvIHBhZ2VzIG9yIEFQSSByZXBsaWVzICh0aGV5IGFyZSBsb2dnZWQgaW5zdGVhZCkuCmRpc3BsYXlfZXJyb3JzID0gMApodG1sX2Vycm9ycyA9IDAKbG9nX2Vycm9ycyA9IDEK',
    'app/.htaccess' => 'IyBTb3VyY2UgZmlsZXMgaW4gdGhpcyBmb2xkZXIgbXVzdCBuZXZlciBiZSBzZXJ2ZWQgdG8gdmlzaXRvcnMuCjxJZk1vZHVsZSBtb2RfYXV0aHpfY29yZS5jPgogICAgUmVxdWlyZSBhbGwgZGVuaWVkCjwvSWZNb2R1bGU+CjxJZk1vZHVsZSAhbW9kX2F1dGh6X2NvcmUuYz4KICAgIE9yZGVyIGFsbG93LGRlbnkKICAgIERlbnkgZnJvbSBhbGwKPC9JZk1vZHVsZT4K',
    'app/lib.php' => '',
    'app/routes.php' => '',
    'app/module-content.json' => '',
);

$ROOT = rtrim(str_replace('\\', '/', __DIR__), '/');
$base = rtrim(str_replace('\\', '/', dirname(isset($_SERVER['SCRIPT_NAME']) ? $_SERVER['SCRIPT_NAME'] : '/')), '/');
$scheme = (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off') ? 'https' : 'http';
$home = $scheme . '://' . (isset($_SERVER['HTTP_HOST']) ? $_SERVER['HTTP_HOST'] : 'localhost') . $base . '/';
function h($s) { return htmlspecialchars((string) $s, ENT_QUOTES, 'UTF-8'); }

function real_password_set($root) {
    if (!is_file($root . '/config.php')) return false;
    $c = @include $root . '/config.php';
    return is_array($c) && !empty($c['admin_password']) && $c['admin_password'] !== 'CHANGE-ME-TO-A-LONG-PASSWORD';
}
$alreadyInstalled = is_file($ROOT . '/app/lib.php') && is_file($ROOT . '/app/routes.php') && is_file($ROOT . '/.htaccess') && is_file($ROOT . '/js/app.js') && is_file($ROOT . '/css/style.css');

$problems = array();
if (PHP_VERSION_ID < 70400) $problems[] = 'This server runs PHP ' . PHP_VERSION . '. The LMS needs PHP 7.4 or newer (cPanel → Select PHP Version).';
if (!extension_loaded('pdo_sqlite')) $problems[] = 'The SQLite extension is off. In cPanel → Select PHP Version tick "pdo_sqlite" and "sqlite3", then Save and reload.';
if (!is_writable($ROOT)) $problems[] = 'This folder is not writable by the web server: ' . $ROOT . ' (set its permissions to 755).';

$errors = array(); $done = false; $failed = array();
$adminId = 'admin';
if ($_SERVER['REQUEST_METHOD'] === 'POST' && !$problems && !$alreadyInstalled) {
    $adminId = trim(isset($_POST['admin_id']) ? $_POST['admin_id'] : 'admin');
    $pw = isset($_POST['pw']) ? (string) $_POST['pw'] : ''; $pw2 = isset($_POST['pw2']) ? (string) $_POST['pw2'] : '';
    $keepPw = real_password_set($ROOT) && $pw === '';
    if (!preg_match('/^[A-Za-z0-9._@-]{3,40}$/', $adminId)) $errors[] = 'Admin ID must be 3–40 characters: letters, numbers, dot, dash or underscore.';
    if (!$keepPw) {
        if (strlen($pw) < 10) $errors[] = 'Please choose a password of at least 10 characters.';
        if ($pw !== $pw2) $errors[] = 'The two passwords do not match.';
    }
    if (!$errors) {
        foreach ($FILES as $rel => $b64) {
            $path = $ROOT . '/' . $rel; $dir = dirname($path);
            if (!is_dir($dir) && !@mkdir($dir, 0755, true)) { $failed[] = $rel . ' (could not create folder)'; continue; }
            $bytes = base64_decode($b64);
            if (@file_put_contents($path, $bytes) === false || md5_file($path) !== md5($bytes)) { $failed[] = $rel; continue; }
            @chmod($path, 0644);
        }
        if (!$keepPw && !$failed) {
            $cfg = "<?php\n// Doctyn Academy FCCM LMS - settings (edit in File Manager if you ever need to).\nreturn array(\n"
                . "    'admin_id'       => " . var_export($adminId, true) . ",\n"
                . "    'admin_password' => " . var_export($pw, true) . ",\n"
                . "    // Leave blank: the database and uploads are kept in a folder called doctyn-fccm-data next to public_html (outside the website).\n"
                . "    'data_dir'       => '',\n    'max_upload_mb'  => 512,\n    'trust_proxy'    => false,\n);\n";
            if (@file_put_contents($ROOT . '/config.php', $cfg) === false) $failed[] = 'config.php';
            else @chmod($ROOT . '/config.php', 0644);
        }
        if (!$failed) { $done = true; @unlink(__FILE__); }
    }
}
?><!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Install Doctyn Academy FCCM LMS</title>
<style>
body{font-family:system-ui,-apple-system,Segoe UI,sans-serif;max-width:620px;margin:6vh auto;padding:0 1.1rem;color:#101B33;line-height:1.55;background:#F5F8FF}
.card{background:#fff;border:1px solid #D7E3FA;border-radius:18px;padding:1.6rem;box-shadow:0 18px 40px -26px rgba(10,46,122,.35)}
h1{color:#14275C;margin:.2rem 0 .8rem} label{display:block;font-weight:700;font-size:.9rem;margin:.9rem 0 .3rem}
input{font:inherit;width:100%;padding:.7rem .8rem;border:1.5px solid #D7E3FA;border-radius:10px;box-sizing:border-box}
