a.btn{display:block;text-align:center;background:#3FA34D;color:#fff;font-weight:800;border-radius:10px;padding:.85rem;text-decoration:none;margin-top:1rem}.d{color:#4A5578;font-size:.9rem}code{background:#E3ECFF;padding:.1rem .35rem;border-radius:5px}
</style></head><body><div class="card">
<h1>Install Doctyn Academy FCCM LMS</h1>
<?php if ($done): ?>
  <div class="ok">✅ Installed. <?php echo count($FILES); ?> files were created and this installer has been removed.</div>
  <p>Sign in with Admin ID <b><?php echo h($adminId); ?></b> and the password you just chose.</p>
  <a class="btn" href="<?php echo h($home); ?>">Open the LMS →</a>
  <p class="d">Your database and uploaded videos will be kept in a folder named <code>doctyn-fccm-data</code> next to <code>public_html</code>. Back it up now and then.
  If something looks wrong, open <a href="check.php">check.php</a> (and delete it when everything is green).</p>
<?php elseif ($alreadyInstalled): ?>
  <div class="ok">The LMS is already installed here.</div>
  <p>For safety, <b>delete this file (<code>install.php</code>)</b> in File Manager, then <a href="<?php echo h($home); ?>">open the LMS</a>.</p>
<?php elseif ($problems): ?>
  <p>Fix these first, then reload this page:</p><?php foreach ($problems as $p) echo '<div class="err">' . h($p) . '</div>'; ?>
<?php else: ?>
  <p>This creates every file the LMS needs in <code><?php echo h($ROOT); ?></code> and sets up your administrator login. It takes a few seconds.</p>
  <?php foreach ($errors as $e) echo '<div class="err">' . h($e) . '</div>'; ?>
  <?php foreach ($failed as $f) echo '<div class="err">Could not write: ' . h($f) . '. Check this folder is writable (permissions 755), then try again.</div>'; ?>
  <form method="post" autocomplete="off">
    <label for="admin_id">Admin ID (what you type to sign in)</label><input id="admin_id" name="admin_id" value="<?php echo h($adminId); ?>" required>
    <label for="pw">Admin password (at least 10 characters)</label><input id="pw" name="pw" type="password" autocomplete="new-password" <?php echo real_password_set($ROOT) ? '' : 'required'; ?>>
    <label for="pw2">Repeat the password</label><input id="pw2" name="pw2" type="password" autocomplete="new-password" <?php echo real_password_set($ROOT) ? '' : 'required'; ?>>
    <?php if (real_password_set($ROOT)): ?><p class="d">A password is already set in config.php — leave both boxes empty to keep it.</p><?php endif; ?>
    <button>Install</button>
  </form>
<?php endif; ?>
</div></body></html>
